from cpmpy import *

h = boolvar(shape=(m, n - 1), name="h")  # horizontal domino starts
v = boolvar(shape=(m - 1, n), name="v")  # vertical domino starts

model = Model()
for i in range(m):
    for j in range(n):
        cover = []
        if j > 0:
            cover.append(h[i, j - 1])
        if j < n - 1:
            cover.append(h[i, j])
        if i > 0:
            cover.append(v[i - 1, j])
        if i < m - 1:
            cover.append(v[i, j])
        model += (sum(cover) == 1)

if model.solve():
    print(h.value())
    print(v.value())
